from pathlib import Path
import sys

path = Path(sys.argv[1])
text = path.read_text(encoding='utf-8')

def replace_once(old: str, new: str, label: str):
    global text
    count = text.count(old)
    if count != 1:
        raise AssertionError(f'{label}: expected exactly one match, got {count}')
    text = text.replace(old, new, 1)

text = text.replace('20260820-cost-visibility-r1', '20260820-allin-price-r1')

old_assess = '''    const price = this._num(c.price_entity, NaN);\n    const costPerHour = Number.isFinite(sitePower) && Number.isFinite(price)\n      ? Math.max(0, sitePower) / 1000 * price\n      : NaN;\n\n    const monthEnergy = this._num(c.month_energy, NaN);\n    const fixedMonthly = this._num(c.fixed_monthly, NaN);\n    const parentMonthEnergy = Number(this._history?.parentMonth);\n    const siteMonthEnergy = Number.isFinite(monthEnergy) && Number.isFinite(parentMonthEnergy)\n      ? Math.max(0, monthEnergy) + Math.max(0, parentMonthEnergy)\n      : NaN;\n    const siteMonthCost = Number.isFinite(siteMonthEnergy) && Number.isFinite(price) && Number.isFinite(fixedMonthly)\n      ? Math.max(0, siteMonthEnergy) * price + Math.max(0, fixedMonthly)\n      : NaN;\n    const monthComplete = Boolean(this._history?.monthComplete);\n'''
new_assess = '''    const price = this._num(c.price_entity, NaN);\n    const monthEnergy = this._num(c.month_energy, NaN);\n    const fixedMonthly = this._num(c.fixed_monthly, NaN);\n    const parentMonthActual = Number(this._history?.parentMonth);\n    const monthComplete = Boolean(this._history?.monthComplete);\n\n    // Finance UX is deliberately all-in. For the partial first smart month,\n    // estimate only the missing pre-smart parent consumption from the archived\n    // long-term branch ratio, then combine it with actual smart parent kWh.\n    const smartMonthTomas = Number(this._history?.tomas);\n    const financeAnchorTomas = Number(c.historical_anchor_tomas_kwh);\n    const financeAnchorParents = Number(c.historical_anchor_parents_kwh);\n    const financeParentRatio = Number.isFinite(financeAnchorTomas) && financeAnchorTomas > 0\n      && Number.isFinite(financeAnchorParents)\n      ? Math.max(0, financeAnchorParents) / Math.max(0.001, financeAnchorTomas)\n      : NaN;\n    const rootBeforeSmart = !monthComplete && Number.isFinite(monthEnergy) && Number.isFinite(smartMonthTomas)\n      ? Math.max(0, monthEnergy - Math.max(0, smartMonthTomas))\n      : 0;\n    const parentBeforeSmartEstimate = !monthComplete && Number.isFinite(financeParentRatio)\n      ? rootBeforeSmart * financeParentRatio\n      : 0;\n    const parentMonthEnergy = Number.isFinite(parentMonthActual)\n      ? Math.max(0, parentMonthActual) + parentBeforeSmartEstimate\n      : NaN;\n    const siteMonthEnergy = Number.isFinite(monthEnergy) && Number.isFinite(parentMonthEnergy)\n      ? Math.max(0, monthEnergy) + Math.max(0, parentMonthEnergy)\n      : NaN;\n    const siteMonthCost = Number.isFinite(siteMonthEnergy) && Number.isFinite(price) && Number.isFinite(fixedMonthly)\n      ? Math.max(0, siteMonthEnergy) * price + Math.max(0, fixedMonthly)\n      : NaN;\n    const effectivePrice = Number.isFinite(siteMonthCost) && Number.isFinite(siteMonthEnergy) && siteMonthEnergy > 0\n      ? siteMonthCost / siteMonthEnergy\n      : NaN;\n    const costPerHour = Number.isFinite(sitePower) && Number.isFinite(effectivePrice)\n      ? Math.max(0, sitePower) / 1000 * effectivePrice\n      : NaN;\n    const monthEstimated = !monthComplete && Number.isFinite(financeParentRatio)\n      && Number.isFinite(parentMonthEnergy);\n'''
replace_once(old_assess, new_assess, 'assess finance block')

old_return = '''      price, costPerHour, monthEnergy, fixedMonthly,\n      month: {\n        parents: parentMonthEnergy,\n        total: siteMonthEnergy,\n        cost: siteMonthCost,\n        complete: monthComplete,\n        from: this._history?.monthFrom ?? null,\n      },\n'''
new_return = '''      price, effectivePrice, costPerHour, monthEnergy, fixedMonthly,\n      month: {\n        parents: parentMonthEnergy,\n        total: siteMonthEnergy,\n        cost: siteMonthCost,\n        effectivePrice,\n        complete: monthComplete,\n        estimated: monthEstimated,\n        from: this._history?.monthFrom ?? null,\n      },\n'''
replace_once(old_return, new_return, 'assess return block')

old_key = '''      a.sitePower, a.siteCurrent, a.price, a.costPerHour,\n      a.monthEnergy, a.fixedMonthly, a.month.parents, a.month.total, a.month.cost, a.month.complete,\n'''
new_key = '''      a.sitePower, a.siteCurrent, a.price, a.effectivePrice, a.costPerHour,\n      a.monthEnergy, a.fixedMonthly, a.month.parents, a.month.total, a.month.cost, a.month.complete, a.month.estimated,\n'''
replace_once(old_key, new_key, 'render key finance fields')

old_render = '''    const priceText = Number.isFinite(a.price)\n      ? `${this._fmt(a.price, 2)} Kč/kWh`\n      : "—";\n\n    const costText = Number.isFinite(a.costPerHour)\n      ? `≈ ${this._fmt(a.costPerHour, a.costPerHour < 10 ? 2 : 1)} Kč/h`\n      : "—";\n\n    const fixedText = Number.isFinite(a.fixedMonthly)\n      ? `${this._fmt(a.fixedMonthly, 2)} Kč`\n      : "—";\n\n    const monthEnergyUnit = this._st(c.month_energy)?.attributes?.unit_of_measurement || "kWh";\n\n    const monthEnergyText = Number.isFinite(a.month.total)\n      ? `${this._fmt(a.month.total, a.month.total >= 100 ? 0 : 2)} ${monthEnergyUnit}`\n      : "—";\n\n    const monthCostText = Number.isFinite(a.month.cost)\n      ? `${this._fmt(a.month.cost, 2)} Kč`\n      : "—";\n\n    const monthEnergyLabel = a.month.complete ? "Markvarec tento měsíc" : "Známé minimum měsíce";\n    const monthCostLabel = a.month.complete ? "Cena měsíce vč. fixu" : "Min. cena vč. fixu";\n\n    const rateDetail = Number.isFinite(a.price)\n      ? `obě kořenové větve · ${priceText} proměnná · bez měsíčního fixu`\n      : "Cena není dostupná";\n'''
new_render = '''    const finalPriceText = Number.isFinite(a.effectivePrice)\n      ? `${this._fmt(a.effectivePrice, 2)} Kč/kWh`\n      : "—";\n\n    const costText = Number.isFinite(a.costPerHour)\n      ? `≈ ${this._fmt(a.costPerHour, a.costPerHour < 10 ? 2 : 1)} Kč/h`\n      : "—";\n\n    const monthEnergyUnit = this._st(c.month_energy)?.attributes?.unit_of_measurement || "kWh";\n\n    const monthEnergyText = Number.isFinite(a.month.total)\n      ? `${this._fmt(a.month.total, a.month.total >= 100 ? 0 : 2)} ${monthEnergyUnit}`\n      : "—";\n\n    const monthCostText = Number.isFinite(a.month.cost)\n      ? `${this._fmt(a.month.cost, 2)} Kč`\n      : "—";\n\n    const monthEnergyLabel = a.month.complete ? "Spotřeba měsíce" : "Odhad spotřeby";\n    const monthCostLabel = a.month.complete ? "Cena měsíce" : "Odhad ceny měsíce";\n    const coverageText = a.month.complete ? "KOMPLETNÍ" : (a.month.estimated ? "ODHAD" : "NEÚPLNÉ");\n\n    const rateDetail = Number.isFinite(a.effectivePrice)\n      ? `${a.month.complete ? "konečná efektivní cena" : "odhad konečné efektivní ceny"} ${finalPriceText}`\n      : "Konečná cena zatím není dostupná";\n'''
replace_once(old_render, new_render, 'render finance text block')

old_meta = '''          <div class="meta">\n            <button data-entity="${this._esc(c.price_entity)}">\n              <small>Cena za kWh</small>\n              <strong>${this._esc(priceText)}</strong>\n            </button>\n\n            <button data-entity="${this._esc(c.fixed_monthly)}">\n              <small>Fix / měsíc</small>\n              <strong>${this._esc(fixedText)}</strong>\n            </button>\n\n            <button title="Součet Tomášovy měsíční spotřeby a dostupné rodičovské smart spotřeby">\n              <small>${this._esc(monthEnergyLabel)}</small>\n              <strong>${this._esc(monthEnergyText)}</strong>\n            </button>\n\n            <button title="Proměnná cena známé spotřeby + právě jeden společný měsíční fix">\n              <small>${this._esc(monthCostLabel)}</small>\n              <strong>${this._esc(monthCostText)}</strong>\n            </button>\n          </div>\n'''
new_meta = '''          <div class="meta">\n            <button title="Výsledná efektivní cena za kWh podle celkového měsíčního nákladu a spotřeby">\n              <small>Konečná cena</small>\n              <strong>${this._esc(finalPriceText)}</strong>\n            </button>\n\n            <button title="${a.month.complete ? "Rodičovská větev má smart data za celý měsíc" : "Chybějící část rodičovské spotřeby je dopočtená z dlouhodobého poměru větví"}">\n              <small>Měsíční data</small>\n              <strong>${this._esc(coverageText)}</strong>\n            </button>\n\n            <button title="Celková spotřeba obou kořenových větví za měsíc; v prvním neúplném smart měsíci je rodičovská část dopočtená">\n              <small>${this._esc(monthEnergyLabel)}</small>\n              <strong>${this._esc(monthEnergyText)}</strong>\n            </button>\n\n            <button title="Výsledný celkový náklad za měsíc podle aktuálního cenového modelu; na kartě se jednotlivé tarifní složky nerozepisují">\n              <small>${this._esc(monthCostLabel)}</small>\n              <strong>${this._esc(monthCostText)}</strong>\n            </button>\n          </div>\n'''
replace_once(old_meta, new_meta, 'meta finance tiles')

# Guard: tariff components may remain in internal calculation/config, but must not be visible in rendered copy.
for forbidden in ('Fix / měsíc', 'bez měsíčního fixu', 'Cena měsíce vč. fixu', 'Min. cena vč. fixu', '<small>Cena za kWh</small>'):
    if forbidden in text:
        raise AssertionError(f'visible legacy finance copy remains: {forbidden}')

path.write_text(text, encoding='utf-8')
print(f'ENERGY_ALLIN_PATCH_OK bytes={len(text.encode("utf-8"))}')
